with t as (select unnest(array["homeTeamId","awayTeamId"]) team_id from games where date='2026-11-16') select t.team_id, (select count(*) from rosters r where r."teamId"=t.team_id and r."seasonId"=20262027 and r.is_current) roster_cur, (select count(*) from rosters r join players p on p.id=r."playerId" where r."teamId"=t.team_id and r."seasonId"=20262027 and r.is_current and p.position<>'G') roster_skaters, (select count(*) from rosters r join players p on p.id=r."playerId" where r."teamId"=t.team_id and r."seasonId"=20262027 and r.is_current and p.position='G') roster_goalies, (select count(*) from forge_player_projections pp where pp.run_id='26373189-3ebd-4380-b4f4-c6797d469ca9' and pp.team_id=t.team_id) proj_skaters, (select count(*) from forge_goalie_projections gp where gp.run_id='26373189-3ebd-4380-b4f4-c6797d469ca9' and gp.team_id=t.team_id) proj_goalies from t
